package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.LocalDate;
import java.time.Month;
import java.time.MonthDay;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class ModernPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE;
    private static final DateTimeFormatter INSTANT_FORMATTER = DateTimeFormatter.ISO_OFFSET_DATE_TIME;
    private static final LocalTime CUTOFF_TIME = LocalTime.of(16, 0, 0);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(Month.JANUARY, 1),
            MonthDay.of(Month.JANUARY, 6),
            MonthDay.of(Month.MAY, 1),
            MonthDay.of(Month.MAY, 3),
            MonthDay.of(Month.AUGUST, 15),
            MonthDay.of(Month.NOVEMBER, 1),
            MonthDay.of(Month.NOVEMBER, 11),
            MonthDay.of(Month.DECEMBER, 25),
            MonthDay.of(Month.DECEMBER, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate d = parseLocalDate(date);
        return isBusinessDay(d);
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = parseZonedDateTime(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate localDate = zdt.toLocalDate();
        LocalTime localTime = zdt.toLocalTime();

        if (isBusinessDay(localDate) && (localTime.isBefore(CUTOFF_TIME) || localTime.equals(CUTOFF_TIME))) {
            return localDate.toString();
        } else {
            return nextBusinessDay(localDate).toString();
        }
    }

    @Override
    public String settlementDate(String submittedAt) {
        ZonedDateTime zdt = parseZonedDateTime(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate procDate = processingDateInternal(zdt.toLocalDate(), zdt.toLocalTime());
        return nextBusinessDay(procDate).toString();
    }

    private LocalDate processingDateInternal(LocalDate localDate, LocalTime localTime) {
        if (isBusinessDay(localDate) && (localTime.isBefore(CUTOFF_TIME) || localTime.equals(CUTOFF_TIME))) {
            return localDate;
        } else {
            return nextBusinessDay(localDate);
        }
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseLocalDate(dueDate);
        ZonedDateTime paid = parseZonedDateTime(paidAt).withZoneSameInstant(BANK_ZONE);
        LocalDate paidDate = paid.toLocalDate();

        long late = ChronoUnit.DAYS.between(due, paidDate);
        return (int) Math.max(0, late);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate d = parseLocalDate(date);
        boolean isLastDay = d.getDayOfMonth() == d.lengthOfMonth();
        LocalDate result = d.plusMonths(months);
        if (isLastDay) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.toString();
    }

    private boolean isBusinessDay(LocalDate date) {
        int dow = date.getDayOfWeek().getValue();
        if (dow == 6 || dow == 7) {
            return false;
        }
        return !HOLIDAYS.contains(MonthDay.from(date));
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate result = date;
        do {
            result = result.plusDays(1);
        } while (!isBusinessDay(result));
        return result;
    }

    private LocalDate parseLocalDate(String text) {
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("INVALID DATE");
        }
        try {
            return LocalDate.parse(text, DATE_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID DATE: " + text, e);
        }
    }

    private ZonedDateTime parseZonedDateTime(String text) {
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("INVALID TIMESTAMP");
        }
        try {
            return ZonedDateTime.parse(text, INSTANT_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID TIMESTAMP: " + text, e);
        }
    }
}

